47	// ── Shared helpers ──────────────────────────────────────────────────────────────
48	
49	/// A request that is no longer approvable — absent, terminal, or lapsed — maps to one uniform
50	/// response so the caller can't probe request state beyond "pending or not".
51	fn not_approvable() -> ApiError {
52	    ApiError::new(
53	        ErrorCode::NotFound,
54	        "authorization request not found or expired",
55	    )
56	}
57	
58	/// Signature / authority / binding failures share one message so the surface reveals nothing about
59	/// which check failed.
60	fn approval_rejected() -> ApiError {
61	    ApiError::new(
62	        ErrorCode::AuthenticationRequired,
63	        "consent approval rejected",
64	    )
65	}
66	
67	/// Reduce the wallet's requested granted-scope string to the tokens actually on offer: `atproto` is
68	/// always granted (never optional), and every other token is kept only if it was part of the
69	/// request's snapshotted `requested_scope`. This mirrors `oauth_authorize`'s reduction filter, so a
70	/// tampered/injected token that was never requested cannot add scope — only narrow it.
71	fn reduce_granted_scope(requested_scope: &str, wallet_granted: &str) -> String {
72	    let wallet: Vec<&str> = wallet_granted.split_whitespace().collect();
73	    requested_scope
74	        .split_whitespace()
75	        .filter(|t| *t == "atproto" || wallet.contains(t))
76	        .collect::<Vec<_>>()
77	        .join(" ")
78	}
