103	/// `GET /oauth/authorize/consent-request` — the wallet's preview of a pending request, resolved by
104	/// `user_code` (typed) or `request_id` (handoff). Returns 404 for anything not currently pending so
105	/// a guessed code reveals nothing.
106	pub async fn get_consent_request(
107	    State(state): State<AppState>,
108	    Query(query): Query<ConsentRequestQuery>,
109	) -> Result<Json<ConsentRequestPreview>, ApiError> {
110	    let pending = match (&query.user_code, &query.request_id) {
111	        (Some(code), None) => get_pending_by_user_code(&state.db, code).await?,
112	        (None, Some(request_id)) => get_pending_by_request_id(&state.db, request_id).await?,
113	        _ => {
114	            return Err(ApiError::new(
115	                ErrorCode::InvalidRequest,
116	                "exactly one of userCode or requestId is required",
117	            ))
118	        }
119	    };
120	    let pending = pending.filter(|p| p.status == "pending" && !p.is_expired);
121	    let Some(p) = pending else {
122	        return Err(not_approvable());
123	    };
124	    Ok(Json(ConsentRequestPreview {
125	        request_id: p.request_id,
126	        client_id: p.client_id,
127	        client_name: p.client_name,
128	        redirect_uri: p.redirect_uri,
129	        origin: p.origin,
130	        ip: p.ip,
131	        requested_scope: p
132	            .requested_scope
133	            .split_whitespace()
134	            .map(str::to_string)
135	            .collect(),
136	        login_hint: p.login_hint,
137	    }))
138	}
