150	}
151	
152	/// `GET /oauth/authorize/status?request_id=…` — the consent page's poll. Throttled per request with
153	/// the `slow_down` discipline (429 when polled faster than `STATUS_POLL_MIN_INTERVAL`), and reports
154	/// a derived `expired` for a lapsed or reclaimed request so the page stops.
155	pub async fn get_authorization_status(
156	    State(state): State<AppState>,
157	    Query(query): Query<StatusQuery>,
158	) -> Response {
159	    // slow_down throttle, reusing the shared poll tracker with a namespaced key so it can't collide
160	    // with agent claim-poll marks. A poll faster than the interval gets a 429 the page backs off on.
161	    {
162	        let key = format!("consent:{}", query.request_id);
163	        let mut tracker = state.poll_tracker.lock().unwrap_or_else(|e| e.into_inner());
164	        if let Some(last) = tracker.get(&key) {
165	            if last.elapsed() < STATUS_POLL_MIN_INTERVAL {
166	                return (
167	                    StatusCode::TOO_MANY_REQUESTS,
168	                    Json(StatusResponse {
169	                        status: "slow_down",
170	                    }),
171	                )
172	                    .into_response();
173	            }
174	        }
175	        tracker.insert(key, Instant::now());
176	    }
177	
178	    let pending = match get_pending_by_request_id(&state.db, &query.request_id).await {
179	        Ok(p) => p,
180	        Err(e) => return e.into_response(),
181	    };
182	    let status = match pending {
183	        // Absent (never created or reclaimed) reads as expired so the page stops polling.
184	        None => "expired",
185	        Some(p) if p.status == "pending" && p.is_expired => "expired",
186	        Some(p) => match p.status.as_str() {
187	            "pending" => "pending",
188	            "approved" => "approved",
189	            "denied" => "denied",
190	            "completed" => "completed",
191	            _ => "expired",
192	        },
193	    };
194	    Json(StatusResponse { status }).into_response()
195	}
