223	/// `POST /oauth/authorize/approve` — verify a device-key-signed approve/deny envelope against the
224	/// account's authoritative current signing authority and terminate the request accordingly.
225	pub async fn post_authorization_approve(
226	    State(state): State<AppState>,
227	    Json(request): Json<ApprovalRequest>,
228	) -> Result<Json<ApprovalResponse>, ApiError> {
229	    // 1. Cheap syntactic gates before any DB or network work.
230	    let signature = decode_canonical_base64url(&request.signature, SIGNATURE_BYTES)
231	        .and_then(|bytes| <[u8; SIGNATURE_BYTES]>::try_from(bytes).ok())
232	        .ok_or_else(approval_rejected)?;
233	    if decode_canonical_base64url(&request.nonce, NONCE_BYTES).is_none() {
234	        return Err(approval_rejected());
235	    }
236	    let approve = match request.decision.as_str() {
237	        crypto::OAUTH_CONSENT_DECISION_APPROVE => true,
238	        crypto::OAUTH_CONSENT_DECISION_DENY => false,
239	        _ => return Err(approval_rejected()),
240	    };
241	    let now = crate::time::unix_now_secs();
242	    if now.abs_diff(request.timestamp) > SOVEREIGN_TIMESTAMP_WINDOW_SECS as u64 {
243	        return Err(approval_rejected());
244	    }
245	
246	    // 2. Load the pending request; it must be currently approvable.
247	    let pending = get_pending_by_request_id(&state.db, &request.request_id)
248	        .await?
249	        .filter(|p| p.status == "pending" && !p.is_expired)
250	        .ok_or_else(not_approvable)?;
251	
252	    // 3. Account binding: a pre-bound login_hint must match the approving DID; otherwise the wallet
253	    //    binds its own DID here (like the agent claim confirm). Either way the DID must be a local
254	    //    active account so the authorization code can be issued against it.
255	    if let Some(hint) = pending.login_hint.as_deref() {
256	        if hint != request.did {
257	            return Err(approval_rejected());
258	        }
259	    }
260	    if !crate::db::accounts::active_local_account_exists(&state.db, &request.did).await? {
261	        return Err(approval_rejected());
262	    }
263	
264	    // 4. The granted scope the wallet signed over is the verbatim `granted_scope` string (empty for
265	    //    a denial); the stored set is that, reduced to what was actually requested.
266	    let signed_scope = if approve {
267	        request.granted_scope.as_str()
268	    } else {
269	        ""
270	    };
271	    let stored_scope = reduce_granted_scope(&pending.requested_scope, signed_scope);
272	
273	    // 5. Verify the envelope signature, then confirm the signing key is in the account's
274	    //    authoritative current signing authority (never the cached DID doc). Signature first, so an
275	    //    invalid signature never triggers the outbound authority lookup.
276	    let server_did = state.config.resolve_server_did();
277	    let envelope = crypto::encode_oauth_consent_envelope(
278	        &server_did,
279	        &request.did,
280	        &request.signing_key,
281	        &request.request_id,
282	        &pending.client_id,
283	        &request.decision,
284	        signed_scope,
285	        request.timestamp,
286	        &request.nonce,
287	    );
288	    let signing_key = crypto::DidKeyUri(request.signing_key.clone());
289	    crypto::verify_did_key_signature(&signing_key, &envelope, &signature)
290	        .map_err(|_| approval_rejected())?;
291	
292	    let authority = authorized_signing_keys(&state, &request.did)
293	        .await
294	        .map_err(|error| match error {
295	            AuthorityError::Unauthorized(_) => approval_rejected(),
296	            AuthorityError::Lookup(err) => err,
297	        })?;
298	    if !authority.authorizes(&request.signing_key) {
299	        return Err(approval_rejected());
300	    }
301	
302	    // 6. Terminate the request and audit it in one transaction. The guarded UPDATE is the single-use
303	    //    point: a replayed envelope lands on an already-terminal row and wins nothing.
304	    let mut tx = state.db.begin().await.map_err(|e| {
305	        tracing::error!(error = %e, "failed to begin consent approval transaction");
306	        ApiError::new(ErrorCode::InternalError, "failed to record decision")
307	    })?;
308	    let won = if approve {
309	        approve_pending_authorization(&mut *tx, &request.request_id, &request.did, &stored_scope)
310	            .await?
311	    } else {
312	        deny_pending_authorization(&mut *tx, &request.request_id, &request.did).await?
313	    };
314	    if !won {
315	        return Err(ApiError::new(
316	            ErrorCode::InvalidRequest,
317	            "authorization request already resolved",
318	        ));
319	    }
320	    let (event, detail) = if approve {
321	        (
322	            OAuthConsentAuditEventType::Approved,
323	            serde_json::json!({ "granted_scope": stored_scope }).to_string(),
324	        )
325	    } else {
326	        (
327	            OAuthConsentAuditEventType::Denied,
328	            serde_json::json!({}).to_string(),
329	        )
330	    };
331	    insert_oauth_consent_audit_event(
332	        &mut *tx,
333	        &uuid::Uuid::new_v4().to_string(),
334	        &request.request_id,
335	        Some(&request.did),
336	        &pending.client_id,
337	        event,
338	        Some(&detail),
339	    )
340	    .await?;

1	// pattern: Imperative Shell
2	//
3	// The shared "which keys may sign a sovereign proof for this account" lookup, behind the three
4	// passwordless auth surfaces (`POST /v1/sessions/sovereign`, `POST /oauth/authorize/approve`,
5	// and the deletion-proof branch of `POST /xrpc/com.atproto.server.deleteAccount`).
6	// Signature verification is already method-agnostic (`crypto::verify_did_key_signature` over a
7	// `did:key:` URI, P-256 and secp256k1), so the authority lookup is the only place a DID method
8	// matters. It lives here rather than in either route because routes may not import one another.
9	//
10	// Both methods resolve their authority **live** from the authoritative source, never from the
11	// `did_documents` cache — for did:plc because `rotationKeys` is authoritative only in the latest
12	// non-nullified audit-log operation, and for did:web because that cache is writable by
13	// `POST /v1/did-web/document`.
14	
15	use common::ApiError;
16	use serde_json::Value;
17	
18	use crate::app::AppState;
19	
20	use super::plc::fetch_current_plc_state;
21	use super::resolution::resolve_web_did_document;
22	
23	/// The set of `did:key:` URIs currently authorized to sign a sovereign proof for an account,
24	/// plus a short description of the authority state they were read from (for the success log).
25	pub struct AuthoritySet {
26	    keys: Vec<String>,
27	    pub source: String,
28	}
29	
30	impl AuthoritySet {
31	    pub fn authorizes(&self, signing_key: &str) -> bool {
32	        self.keys.iter().any(|key| key == signing_key)
33	    }
34	}
35	
36	/// A failed authority lookup, split by who the caller should blame.
37	pub enum AuthorityError {
38	    /// The DID method, document, or policy denies any authority. The caller collapses this into
39	    /// its own opaque rejection — it must never become a distinguishable response.
40	    Unauthorized(&'static str),
41	    /// The authoritative source could not be consulted. Propagated as-is so an upstream outage
42	    /// still fails closed with its own status (a plc.directory 503 stays a 502, not a 401).
43	    Lookup(ApiError),
44	}
45	
46	fn is_plc_did(value: &str) -> bool {
47	    let Some(suffix) = value.strip_prefix("did:plc:") else {
48	        return false;
49	    };
50	    suffix.len() == 24
51	        && suffix
52	            .bytes()
53	            .all(|byte| byte.is_ascii_lowercase() || (b'2'..=b'7').contains(&byte))
54	}
55	
56	/// Resolve the account's current signing authority from its DID method's authoritative source.
57	pub async fn authorized_signing_keys(
58	    state: &AppState,
59	    did: &str,
60	) -> Result<AuthoritySet, AuthorityError> {
